import { mkdirSync } from 'fs';
import { dirname, join } from 'path';
import type { CallerHandoff, WorkItemInitiator } from './handoff';
import { writeFileAtomicSync } from '../utils/writeFileAtomic';


export const SESSION_HANDOFF_VERSION = 1;

export type SessionHandoffRecord = {
  version: typeof SESSION_HANDOFF_VERSION;
  sessionId: string | null;
  recordedAt: string;
  initiator: WorkItemInitiator;
  handoff: CallerHandoff | null;
};

const OWNER_ONLY_FILE_MODE = 0o600;

export const sessionHandoffPath = (projectPath: string): string =>
  join(projectPath, '.rivet', 'cli', 'handoff.json');

export const writeSessionHandoff = (
  projectPath: string,
  record: Omit<SessionHandoffRecord, 'version' | 'recordedAt'>,
): void => {
  const filePath = sessionHandoffPath(projectPath);
  mkdirSync(dirname(filePath), { recursive: true });
  writeFileAtomicSync(
    filePath,
    JSON.stringify({
      version: SESSION_HANDOFF_VERSION,
      recordedAt: new Date().toISOString(),
      ...record,
    }),
    { mode: OWNER_ONLY_FILE_MODE },
  );
};
